{
  "themes": [
    {
      "name": "Matchmaking and lobby wait times",
      "summary": "Players report long queues and excessive time in the lobby or searching for a match. Some say they spend more time waiting than playing.",
      "severity": "high",
      "comments": [
        {"id": "c029", "quote": "waited 17 mins to get in"},
        {"id": "c059", "quote": "Spent more time in the lobby than in the match"},
        {"id": "c080", "quote": "watching the searching for match spinner"},
        {"id": "c091", "quote": "half an hour per game"},
        {"id": "c089", "quote": "another 30 minute queue"}
      ]
    },
    {
      "name": "Performance and FPS problems",
      "summary": "Players report low frame rates in matches and stutters that make the game hard to play. Even high end hardware and lowered settings do not fix it.",
      "severity": "high",
      "comments": [
        {"id": "c040", "quote": "drop to 40fps on Greywater when it rains"},
        {"id": "c107", "quote": "25 in the match"},
        {"id": "c055", "quote": "big stutter right as i respawn"}
      ]
    },
    {
      "name": "Ability visual clarity",
      "summary": "Players report that ability effects, traps and ult warnings are too faint or blend into the background. This makes them hard to see and dodge.",
      "severity": "high",
      "comments": [
        {"id": "c042", "quote": "no visible edge"},
        {"id": "c117", "quote": "needs a bigger tell"},
        {"id": "c069", "quote": "small glow at the feet"},
        {"id": "c022", "quote": "spell effects blend in with the background"},
        {"id": "c019", "quote": "ability vfx are so faint"},
        {"id": "c012", "quote": "Can't see half the ability effects"}
      ]
    },
    {
      "name": "Voice chat abuse and toxicity",
      "summary": "Players report harassment, slurs, sexist comments and screaming in voice chat. Many mute voice or avoid it entirely.",
      "severity": "high",
      "comments": [
        {"id": "c037", "quote": "heard things on team chat"},
        {"id": "c100", "quote": "got called slurs in voice"},
        {"id": "c054", "quote": "non stop harassment"},
        {"id": "c078", "quote": "hurling insults on voice"},
        {"id": "c096", "quote": "sexist comments on comms"},
        {"id": "c114", "quote": "mic toxicity is out of control"}
      ]
    },
    {
      "name": "Spawn placement",
      "summary": "Players report spawning in front of enemies or in the open, often dying immediately. Some die multiple times before acting.",
      "severity": "high",
      "comments": [
        {"id": "c105", "quote": "fix your spawns"},
        {"id": "c032", "quote": "spawned right in front of their whole team"},
        {"id": "c010", "quote": "spawning right in front of the enemy sniper"},
        {"id": "c008", "quote": "being dropped next to 3 enemies"}
      ]
    },
    {
      "name": "Progression and economy grind",
      "summary": "Players report slow progression, tiny XP and shard rewards, expensive unlocks and repetitive grinding. Some feel pushed toward paying.",
      "severity": "medium",
      "comments": [
        {"id": "c065", "quote": "Progress is way too slow"},
        {"id": "c120", "quote": "XP per match is tiny"},
        {"id": "c002", "quote": "morrow locked behind 15000 shards"},
        {"id": "c030", "quote": "grind to get the good gear before ranked is just boring"},
        {"id": "c011", "quote": "shards drop so slow"}
      ]
    },
    {
      "name": "Onboarding and tutorial clarity",
      "summary": "Players report that the tutorial rushes through mechanics or fails to explain key terms. They are left confused about charge, cooldown, overcharge and ult use.",
      "severity": "medium",
      "comments": [
        {"id": "c088", "quote": "onboarding assumes you already played hero shooters"},
        {"id": "c013", "quote": "training bit rushes thru"},
        {"id": "c036", "quote": "wtf is overcharge?"},
        {"id": "c023", "quote": "no explanation how to charge it"}
      ]
    },
    {
      "name": "Menu and UI confusion",
      "summary": "Players report confusing menus, unlabeled icons and hidden options. Controller navigation and finding basic features like invites or keybinds is difficult.",
      "severity": "medium",
      "comments": [
        {"id": "c057", "quote": "cursor jumps around the menu"},
        {"id": "c041", "quote": "Half of them go to the same place"},
        {"id": "c066", "quote": "couldnt find keybinds for ages"},
        {"id": "c090", "quote": "what do all these icons mean"},
        {"id": "c077", "quote": "cant figure out how to invite a friend"}
      ]
    }
  ],
  "unassigned": [
    "c086",
    "c050"
  ]
}
